mapper.select:
select ra.*,u.user_name as userName,u.phone,ru.user_name as roomUserName,ru.phone as roomPhone, r.room_name as roomName from room_audit ra left join tb_user u on u.user_id=ra.user_id left join tb_user ru on ru.user_id=ra.room_user_id left join room r on r.room_no=ra.room_no where 1=1
and ra.user_id=#{userId}
and ra.room_user_id=#{userId}
and ra.room_no=#{roomNo}
and r.room_name like concat('%',#{roomName},'%')
and ru.user_name like concat('%',#{roomUserName},'%')
and ru.phone like concat('%',#{roomPhone},'%')
and u.user_name like concat('%',#{userName},'%')
and u.phone like concat('%',#{phone},'%')
and ra.status=#{status}
order by r.create_time desc
